/**
 * Rivela ASE — shared domain contract.
 *
 * This is the single source of truth for wire shapes across db / api / pipeline.
 * - Postgres enum *string values* are kept verbatim (ase_coding_standards.md §2):
 *   snake_case on the wire, camelCase property names in TS.
 * - DTO shapes match ase_api_spec.md exactly.
 * - Do NOT edit this file without updating all three consumers (db repos, api routes, pipeline).
 */

// ---------------------------------------------------------------------------
// Enums (string-literal unions, NOT TS enum — standards §3)
// ---------------------------------------------------------------------------

export type SourceType =
  | 'competitor_website'
  | 'g2'
  | 'capterra'
  | 'trustradius'
  | 'job_board'
  | 'news_rss'
  | 'social_twitter'
  | 'social_linkedin'
  | 'social_reddit'
  | 'gong_chorus'
  | 'salesforce'
  | 'hubspot'
  | 'slack'
  | 'sec_edgar'
  | 'patents';

export type ActionType =
  | 'pricing'
  | 'product'
  | 'personnel'
  | 'messaging'
  | 'partnership'
  | 'funding'
  | 'customer_win'
  | 'regulatory'
  | 'other';

export type ConfidenceLevel = 'high' | 'medium' | 'low';

export type RoutingDecision = 'signal_card' | 'weekly_digest' | 'archive';

export const SOURCE_TYPES: readonly SourceType[] = [
  'competitor_website',
  'g2',
  'capterra',
  'trustradius',
  'job_board',
  'news_rss',
  'social_twitter',
  'social_linkedin',
  'social_reddit',
  'gong_chorus',
  'salesforce',
  'hubspot',
  'slack',
  'sec_edgar',
  'patents',
];

export const ACTION_TYPES: readonly ActionType[] = [
  'pricing',
  'product',
  'personnel',
  'messaging',
  'partnership',
  'funding',
  'customer_win',
  'regulatory',
  'other',
];

export const CONFIDENCE_LEVELS: readonly ConfidenceLevel[] = ['high', 'medium', 'low'];

export const ROUTING_DECISIONS: readonly RoutingDecision[] = [
  'signal_card',
  'weekly_digest',
  'archive',
];

// ---------------------------------------------------------------------------
// Entities (DB rows, snake_case fields mapped to camelCase at the boundary)
// ---------------------------------------------------------------------------

export interface Organization {
  id: string;
  name: string;
  createdAt: string; // ISO timestamp
}

export interface Competitor {
  id: string;
  organizationId: string;
  name: string;
  createdAt: string;
}

export interface DataSource {
  id: string;
  organizationId: string;
  competitorId: string | null; // null = org-wide source (Slack, CRM)
  sourceType: SourceType;
  targetUrl: string | null;
  collectionMethod: string;
  refreshIntervalMinutes: number;
  isActive: boolean;
  lastCollectedAt: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface RawSignal {
  id: string;
  organizationId: string;
  competitorId: string;
  dataSourceId: string | null;
  sourceType: SourceType;
  rawText: string;
  sourceUrl: string | null;
  collectionMethod: string;
  collectedAt: string;
  contentHash: string;
  ingestedAt: string;
}

export interface Signal {
  id: string;
  rawSignalId: string;
  organizationId: string;
  competitorId: string;
  // Stage 1: classification
  actionType: ActionType;
  confidenceLevel: ConfidenceLevel;
  keyFacts: string[];
  llmModelUsed: string | null;
  classifiedAt: string | null;
  // Stage 2: scoring
  scoreRecency: number;
  scoreSourceAuthority: number;
  scoreActionType: number;
  scoreIcpRelevance: number;
  scoreDealStageContext: number;
  scoreNovelty: number;
  significanceScore: number; // sum of factors, clamped 1-10 (schema CHECK)
  scoredAt: string | null;
  // Routing outcome
  routingDecision: RoutingDecision;
  battlecardUpdateTriggered: boolean;
  dealAlertCheckTriggered: boolean;
  routedAt: string | null;
  /** User bookmark toggle (schema 002). */
  bookmarked: boolean;
  createdAt: string;
}

/** Joined view: signals + the raw signal's text/metadata (GET /signals/{id}). */
export interface SignalDetail extends Signal {
  rawText: string;
  sourceType: SourceType;
  sourceUrl: string | null;
  collectedAt: string;
  competitorName: string;
}

// ---------------------------------------------------------------------------
// Product entities (schema 002 — users, rules, notifications, battlecards)
// ---------------------------------------------------------------------------

export interface User {
  id: string;
  organizationId: string;
  name: string;
  passwordHash: string;
  createdAt: string;
}

/** Public user shape (never includes passwordHash). */
export interface PublicUser {
  id: string;
  organizationId: string;
  name: string;
}

export interface AlertRuleTriggers {
  /** Minimum significance score (1-10) for the rule to match. */
  minScore?: number;
  /** Only match signals with one of these action types. */
  categories?: ActionType[];
  /** Only match signals about one of these competitors (by id). */
  competitorIds?: string[];
  /** Match when any keyword appears in the signal text (case-insensitive). */
  keywords?: string[];
}

export interface AlertRuleChannel {
  type: 'email' | 'webhook';
  target: string; // email: addr@example.com; webhook: https://...
}

export interface AlertRule {
  id: string;
  organizationId: string;
  name: string;
  description: string;
  enabled: boolean;
  triggers: AlertRuleTriggers;
  channels: AlertRuleChannel[];
  /** When a rule matches, escalate the signal's routing decision to this. */
  routingOverride: RoutingDecision | null;
  firedCount: number;
  createdAt: string;
  updatedAt: string;
}

export interface CreateAlertRuleRequest {
  name: string;
  description?: string;
  enabled?: boolean;
  triggers?: AlertRuleTriggers;
  channels?: AlertRuleChannel[];
  routingOverride?: RoutingDecision | null;
}

export interface UpdateAlertRuleRequest {
  name?: string;
  description?: string;
  enabled?: boolean;
  triggers?: AlertRuleTriggers;
  channels?: AlertRuleChannel[];
  routingOverride?: RoutingDecision | null;
}

export interface Notification {
  id: string;
  organizationId: string;
  signalId: string | null;
  ruleId: string | null;
  title: string;
  body: string;
  channel: string;
  status: 'delivered' | 'failed' | 'pending';
  readAt: string | null;
  createdAt: string;
}

/** Battlecard document content (JSONB) — generated per competitor. */
export interface BattlecardContent {
  competitorName: string;
  summary: string;
  sections: {
    heading: string;
    bullets: string[];
  }[];
  sourceSignals: { id: string; title: string; score: number; sourceUrl: string | null }[];
}

export interface Battlecard {
  competitorId: string;
  content: BattlecardContent;
  generatedAt: string;
  updatedAt: string;
}

/** How a battlecard regeneration was triggered (schema 003). */
export type BattlecardTrigger = 'routing' | 'worker' | 'manual' | 'startup';

/** Append-only history entry snapshotting one regeneration (schema 003). */
export interface BattlecardVersion {
  id: string;
  competitorId: string;
  trigger: BattlecardTrigger;
  content: BattlecardContent;
  sourceSignalCount: number;
  triggeredBySignalId: string | null;
  generatedAt: string;
}

/** Competitor profile for the frontend Competitors view (schema 002 join). */
export interface CompetitorProfile extends Competitor {
  signalCount: number;
  monitoringActive: boolean;
  sources: { id: string; sourceType: SourceType; targetUrl: string | null }[];
}

// ---------------------------------------------------------------------------
// API request/response shapes (ase_api_spec.md)
// ---------------------------------------------------------------------------

export interface CreateDataSourceRequest {
  competitorId: string | null;
  sourceType: SourceType;
  targetUrl: string | null;
  collectionMethod: string;
  refreshIntervalMinutes: number;
}

export interface UpdateDataSourceRequest {
  targetUrl?: string | null;
  refreshIntervalMinutes?: number;
  isActive?: boolean;
}

export interface IngestRawSignalRequest {
  organizationId: string;
  competitorId: string;
  dataSourceId: string | null;
  sourceType: SourceType;
  rawText: string;
  sourceUrl: string | null;
  collectionMethod: string;
  collectedAt: string;
  contentHash: string;
}

/** Stage 1 LLM output submitted by the classification worker. */
export interface ClassifyRequest {
  actionType: ActionType;
  confidenceLevel: ConfidenceLevel;
  keyFacts: string[];
  llmModelUsed: string;
}

/** Stage 2 factor scores submitted by the scoring worker. Server sums + clamps 1-10. */
export interface ScoreRequest {
  scoreRecency: number;
  scoreSourceAuthority: number;
  scoreActionType: number;
  scoreIcpRelevance: number;
  scoreDealStageContext: number;
  scoreNovelty: number;
}

/** Routing outcome submitted by the routing engine worker. */
export interface RouteRequest {
  routingDecision: RoutingDecision;
  battlecardUpdateTriggered: boolean;
  dealAlertCheckTriggered: boolean;
}

export interface Paginated<T> {
  items: T[];
  nextCursor: string | null; // null = no more pages
  limit: number;
}

/** Standard error envelope (spec open item — defaulted). */
export interface ApiError {
  error: string; // machine-readable code, e.g. 'validation_error'
  message: string; // human-readable detail
}

// ---------------------------------------------------------------------------
// LLM boundary (standards §5: validate, never trust)
// ---------------------------------------------------------------------------

/** Raw LLM output of the Stage 1 classifier, before zod validation. */
export interface ClassificationResult {
  actionType: ActionType;
  confidenceLevel: ConfidenceLevel;
  keyFacts: string[]; // 2-3 extracted bullet facts
}
